macro_rules! deps {
    () => {
        Mode!();
    };
}

macro_rules! ChangeRef {
    () => {
        deps!();
        # [doc = " Identify a change that would have to be applied to `lhs` to obtain `rhs`, as provided in [`index()`](crate::index())."] # [derive (Clone , Debug , PartialEq , Eq)] pub enum ChangeRef < 'lhs , 'rhs > { # [doc = " An entry was added to `rhs`."] Addition { # [doc = " The location of the newly added entry in `rhs`."] location : Cow < 'rhs , BStr > , # [doc = " The index into the entries array of `rhs` for full access."] index : usize , # [doc = " The mode of the entry in `rhs`."] entry_mode : gix_index :: entry :: Mode , # [doc = " The object id of the entry in `rhs`."] id : Cow < 'rhs , gix_hash :: oid > , } , # [doc = " An entry was removed from `rhs`."] Deletion { # [doc = " The location the entry that doesn't exist in `rhs`."] location : Cow < 'lhs , BStr > , # [doc = " The index into the entries array of `lhs` for full access."] index : usize , # [doc = " The mode of the entry in `lhs`."] entry_mode : gix_index :: entry :: Mode , # [doc = " The object id of the entry in `lhs`."] id : Cow < 'rhs , gix_hash :: oid > , } , # [doc = " An entry was modified, i.e. has changed its content or its mode."] Modification { # [doc = " The location of the modified entry both in `lhs` and `rhs`."] location : Cow < 'rhs , BStr > , # [doc = " The index into the entries array of `lhs` for full access."] previous_index : usize , # [doc = " The previous mode of the entry, in `lhs`."] previous_entry_mode : gix_index :: entry :: Mode , # [doc = " The previous object id of the entry, in `lhs`."] previous_id : Cow < 'lhs , gix_hash :: oid > , # [doc = " The index into the entries array of `rhs` for full access."] index : usize , # [doc = " The mode of the entry in `rhs`."] entry_mode : gix_index :: entry :: Mode , # [doc = " The object id of the entry in `rhs`."] id : Cow < 'rhs , gix_hash :: oid > , } , # [doc = " An entry was renamed or copied from `lhs` to `rhs`."] # [doc = ""] # [doc = " A rename is effectively fusing together the `Deletion` of the source and the `Addition` of the destination."] Rewrite { # [doc = " The location of the source of the rename or copy operation, in `lhs`."] source_location : Cow < 'lhs , BStr > , # [doc = " The index of the entry before the rename, into the entries array of `rhs` for full access."] source_index : usize , # [doc = " The mode of the entry before the rewrite, in `lhs`."] source_entry_mode : gix_index :: entry :: Mode , # [doc = " The object id of the entry before the rewrite."] # [doc = ""] # [doc = " Note that this is the same as `id` if we require the [similarity to be 100%](super::Rewrites::percentage), but may"] # [doc = " be different otherwise."] source_id : Cow < 'lhs , gix_hash :: oid > , # [doc = " The current location of the entry in `rhs`."] location : Cow < 'rhs , BStr > , # [doc = " The index of the entry after the rename, into the entries array of `rhs` for full access."] index : usize , # [doc = " The mode of the entry after the rename in `rhs`."] entry_mode : gix_index :: entry :: Mode , # [doc = " The object id of the entry after the rename in `rhs`."] id : Cow < 'rhs , gix_hash :: oid > , # [doc = " If true, this rewrite is created by copy, and `source_id` is pointing to its source. Otherwise, it's a rename,"] # [doc = " and `source_id` points to a deleted object, as renames are tracked as deletions and additions of the same"] # [doc = " or similar content."] copy : bool , } , }
    };
}

ChangeRef!()